describe('Background Job Notification Toast', () => {
  beforeEach(() => {
    cy.visit('/jobs');
  });

  it('should display toast notification when background job completes successfully', () => {
    // Intercept the API call for job completion
    cy.intercept('POST', '/api/jobs/complete').as('jobComplete');

    // Click the button to start the background job
    cy.get('[data-testid="start-job-button"]').click();

    // Verify job started
    cy.get('[data-testid="job-status"]').should('contain', 'Processing');

    // Wait for the job completion API call
    cy.wait('@jobComplete');

    // Verify job status updated
    cy.get('[data-testid="job-status"]').should('contain', 'Completed');

    // Verify toast notification appears
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .should('contain', 'Job completed successfully');

    // Verify toast has success styling
    cy.get('[data-testid="toast-notification"]')
      .should('have.class', 'toast-success');

    // Verify toast auto-hides after a delay
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible');
    cy.get('[data-testid="toast-notification"]')
      .then(($toast) => {
        const toastTimeout = parseInt($toast.attr('data-timeout') || 5000);
        cy.wait(toastTimeout + 500);
      });
    cy.get('[data-testid="toast-notification"]').should('not.exist');
  });

  it('should display error toast when background job fails', () => {
    // Intercept the API call and mock a failure response
    cy.intercept('POST', '/api/jobs/complete', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('jobFailed');

    // Click the button to start the background job
    cy.get('[data-testid="start-job-button"]').click();

    // Verify job started
    cy.get('[data-testid="job-status"]').should('contain', 'Processing');

    // Wait for the job completion API call
    cy.wait('@jobFailed');

    // Verify job status updated to failed
    cy.get('[data-testid="job-status"]').should('contain', 'Failed');

    // Verify error toast notification appears
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .should('contain', 'Job failed');

    // Verify toast has error styling
    cy.get('[data-testid="toast-notification"]')
      .should('have.class', 'toast-error');

    // Verify error details are shown in toast
    cy.get('[data-testid="toast-notification"]')
      .should('contain', 'Internal server error');

    // Verify toast does not auto-hide on error
    cy.get('[data-testid="toast-notification"]').should('be.visible');
  });
});
